var o = new ExportOptionsSaveForWeb();   // a concrete subclass
o.format = SaveDocumentType.PNG;
o.PNG8 = false;
app.activeDocument.exportDocument(new File('~/Desktop/out.png'),
    ExportType.SAVEFORWEB, o);

var o = new ExportOptionsIllustrator();
o.path = IllustratorPathType.NAMEDPATH;
o.pathName = 'Cutline';
app.activeDocument.exportDocument(new File('~/Desktop/cutline.ai'),
    ExportType.ILLUSTRATORPATHS, o);

var o = new ExportOptionsSaveForWeb();
o.format = SaveDocumentType.JPEG;
o.quality = 80;
o.includeProfile = true;
app.activeDocument.exportDocument(new File('~/Desktop/banner.jpg'),
    ExportType.SAVEFORWEB, o);

var o = new CameraRAWOpenOptions();
o.settings = CameraRAWSettingsType.CUSTOM;
o.whiteBalance = WhiteBalanceType.DAYLIGHT;
o.exposure = 0.5;
o.colorSpace = ColorSpaceType.ADOBERGB;
o.bitsPerChannel = BitsPerChannelType.SIXTEEN;
app.open(new File('C:/shoot/IMG_0001.CR2'), o);

var o = new DICOMOpenOptions();
o.anonymize = true;
o.rows = 3;
o.columns = 4;
o.reverse = false;
app.open(new File('C:/scans/study.dcm'), o);

var o = new GenericEPSOpenOptions();
o.resolution = 300;
o.mode = OpenDocumentMode.CMYK;
o.antiAlias = true;
o.constrainProportions = true;
app.open(new File('C:/assets/logo.eps'), o);

var o = new GenericPDFOpenOptions();
o.usePageNumber = true;
o.page = 2;
o.cropPage = CropToType.TRIMBOX;
o.resolution = 300;
o.mode = OpenDocumentMode.RGB;
app.open(new File('C:/proofs/brochure.pdf'), o);

var o = new GenericPDFOpenOptions();   // a concrete subclass
o.page = 1;
o.resolution = 150;
app.open(new File('C:/in/flyer.pdf'), o);

var o = new PhotoCDOpenOptions();   // deprecated class
o.pixelSize = PhotoCDSize.LARGE;
o.colorSpace = PhotoCDColorSpace.RGB8;
o.orientation = Orientation.LANDSCAPE;
app.open(new File('C:/archive/img0001.pcd'), o);

var o = new RawFormatOpenOptions();
o.width = 1024;
o.height = 1024;
o.channelNumber = 1;
o.bitsPerChannel = 16;
o.headerSize = 0;
app.open(new File('C:/terrain/height.raw'), o);

var o = new BMPSaveOptions();
o.depth = BMPDepthType.THIRTYTWO;
o.alphaChannels = true;
o.osType = OperatingSystem.WINDOWS;
app.activeDocument.saveAs(new File('~/Desktop/icon.bmp'), o, true);

var o = new DCS1_SaveOptions();
o.DCS = DCSType.COLORCOMPOSITE;
o.encoding = SaveEncoding.BINARY;
o.preview = MacPreviewType.EIGHTBITTIFF;
app.activeDocument.saveAs(new File('~/Desktop/plate.eps'), o, true);

var o = new DCS2_SaveOptions();
o.spotColors = true;
o.multiFileDCS = false;
o.DCS = DCSType.COLORCOMPOSITE;
o.encoding = SaveEncoding.BINARY;
o.preview = MacPreviewType.EIGHTBITTIFF;
app.activeDocument.saveAs(new File('~/Desktop/pack.eps'), o, true);

var doc = app.activeDocument;
doc.pathItems[0].makeClippingPath(0.5);   // optional cut-out
var o = new EPSSaveOptions();
o.encoding = SaveEncoding.BINARY;
o.vectorData = true;
o.preview = MacPreviewType.EIGHTBITTIFF;
doc.saveAs(new File('~/Desktop/product.eps'), o, true);

var o = new GIFSaveOptions();
o.colors = 64;
o.dither = Dither.DIFFUSION;
o.ditherAmount = 75;
o.transparency = true;
o.matte = MatteType.NONE;
app.activeDocument.saveAs(new File('~/Desktop/icon.gif'), o, true);

var o = new JPEGSaveOptions();
o.quality = 10;
o.embedColorProfile = true;
o.matte = MatteType.WHITE;
app.activeDocument.saveAs(new File('~/Desktop/post.jpg'), o, true);

var o = new PDFSaveOptions();
o.embedColorProfile = true;
o.preserveEditing = false;
o.layers = false;
o.optimizeForWeb = true;
o.view = false;
app.activeDocument.saveAs(new File('~/Desktop/poster.pdf'), o, true);

var o = new PhotoshopSaveOptions();
o.layers = true;
o.alphaChannels = true;
o.embedColorProfile = true;
app.activeDocument.saveAs(new File('~/Desktop/master.psd'), o, false);

var o = new PICTFileSaveOptions();
o.resolution = PICTBitsPerPixels.THIRTYTWO;
o.compression = PICTCompression.NONE;
app.activeDocument.saveAs(new File('~/Desktop/legacy.pct'), o, true);

var o = new PICTResourceSaveOptions();
o.resourceID = 128;
o.name = 'Splash';
o.resolution = PICTBitsPerPixels.THIRTYTWO;
app.activeDocument.saveAs(new File('~/Desktop/splash.rsr'), o, true);

var o = new PixarSaveOptions();
o.alphaChannels = true;
app.activeDocument.saveAs(new File('~/Desktop/plate.pxr'), o, true);

var o = new PNGSaveOptions();
o.compression = 6;
o.interlaced = false;
app.activeDocument.saveAs(new File('~/Desktop/logo.png'), o, true);

var o = new RawSaveOptions();
o.alphaChannels = false;
o.spotColors = false;
app.activeDocument.saveAs(new File('~/Desktop/height.raw'), o, true);

var o = new SGIRGBSaveOptions();
o.alphaChannels = true;
o.spotColors = false;
app.activeDocument.saveAs(new File('~/Desktop/plate.sgi'), o, true);

var o = new TargaSaveOptions();
o.resolution = TargaBitsPerPixels.THIRTYTWO;
o.alphaChannels = true;
o.rleCompression = true;
app.activeDocument.saveAs(new File('~/Desktop/title.tga'), o, true);

var o = new TiffSaveOptions();
o.imageCompression = TIFFEncoding.TIFFLZW;   // enum object name unverified
o.layers = false;
o.alphaChannels = false;
o.embedColorProfile = true;
app.activeDocument.saveAs(new File('~/Desktop/print.tif'), o, true);

var doc = app.activeDocument;
var p = doc.pathItems[0];
p.makeSelection(1, true, SelectionType.REPLACE);
p.fillPath(app.foregroundColor, ColorBlendMode.NORMAL, 100, false, 0, true, true);
p.strokePath(ToolType.BRUSH, false);
p.makeClippingPath(0.5);
